def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Quadratic function for linear region of OTFT p-channel Org1."""
    a = parameters[0]
    b = parameters[1]
    c = parameters[2]

    if drain_voltage_abs > parameters[3]:
        return a*gate_voltage_abs + b*drain_voltage_abs + c
    else:
        return a*gate_voltage_abs + b*drain_voltage_abs + c - parameters[4]*(gate_voltage_abs - parameters[5])*(drain_voltage_abs - parameters[3])
